#include <string>
#include <iostream>
#include <iomanip>
class Pet {
public:
    virtual std::string speak(int n = 0) { return "root"; }
    virtual std::string other() const noexcept(true) { return "root other"; }
};
class Dog : public Pet {
public:
    // override final comment before member
    std::string speak(int n = 0) override final { return " override final"; }
    std::string other() const noexcept(true) override final { return "final override"; }
};

